export type obtenerMiDiaResponse200 = {
  data: MiDiaResponseDtoOutput;
  status: 200;
};

export type obtenerMiDiaResponseSuccess = obtenerMiDiaResponse200 & {
  headers: Headers;
};
export type obtenerMiDiaResponse = obtenerMiDiaResponseSuccess;

export const getObtenerMiDiaUrl = (params?: ObtenerMiDiaParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/mi-dia?${stringifiedParams}` : `/api/mi-dia`;
};

/**
 * @summary Observaciones propias del día con su estado
 */
export const obtenerMiDia = async (
  params?: ObtenerMiDiaParams,
  options?: RequestInit,
): Promise<obtenerMiDiaResponse> => {
  const res = await fetch(getObtenerMiDiaUrl(params), {
    ...options,
    method: 'GET',
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: obtenerMiDiaResponse['data'] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as obtenerMiDiaResponse;
};

export const getObtenerMiDiaQueryKey = (params?: ObtenerMiDiaParams) => {
  return [`/api/mi-dia`, ...(params ? [params] : [])] as const;
};

export const getObtenerMiDiaQueryOptions = <
  TData = Awaited<ReturnType<typeof obtenerMiDia>>,
  TError = unknown,
>(
  params?: ObtenerMiDiaParams,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof obtenerMiDia>>, TError, TData>>;
    fetch?: RequestInit;
  },
) => {
  const { query: queryOptions, fetch: fetchOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getObtenerMiDiaQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof obtenerMiDia>>> = ({ signal }) =>
    obtenerMiDia(params, { signal, ...fetchOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof obtenerMiDia>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

